 page.locator('#search').fill('Uji 10');expect(page.locator('#tableBody tr')).to_have_count(1);expect(page.locator('#tableBody')).to_contain_text('Peserta Uji 10');expect(page.locator('#attendancePageInfo')).to_contain_text('Halaman 1 dari 1');page.locator('#search').fill('');page.locator('[data-attendance-filter="recordedAbsent"]').click();expect(page.locator('#tableBody tr')).to_have_count(3);expect(page.locator('#tableBody')).to_contain_text('Sakit');page.locator('[data-attendance-filter="absent"]').click();expect(page.locator('#tableBody tr')).to_have_count(10);page.locator('#attendanceNext').click();expect(page.locator('#tableBody tr')).to_have_count(7);assert page.evaluate('calls.length')==calls
 page.locator('[data-attendance-filter="all"]').click();page.locator('.attendance-tablebox').evaluate('e=>e.scrollTop=100');assert page.locator('.attendance-tablebox th').first.evaluate('e=>e.getBoundingClientRect().top')>=page.locator('.attendance-tablebox').evaluate('e=>e.getBoundingClientRect().top')-1
 # All five session metric cards share one row at the user's desktop size.
 page.set_viewport_size({'width':1349,'height':1050});tops=page.locator('#sessionPanel > .stats > .stat').evaluate_all('els=>els.map(e=>e.getBoundingClientRect().top)');assert len(tops)==5 and max(tops)-min(tops)<1;assert page.evaluate('document.documentElement.scrollWidth<=innerWidth')
 # A row action preselects one editable name, while the standalone path starts empty.
 page.locator('#search').fill('Uji 31');page.locator('#tableBody button[data-manual]').click();expect(page.locator('#manualSearch')).to_have_value('Peserta Uji 31');assert page.locator('#manualPerson').count()==0
 page.locator('#manualSearch').fill('Uji 30');expect(page.locator('#manualSave')).to_be_disabled();page.locator('#manualResults button').first.click();expect(page.locator('#manualSearch')).to_have_value('Peserta Uji 30');page.locator('#manualSearch').fill('');expect(page.locator('#manualSave')).to_be_disabled();page.locator('#manualClose').click()
 page.locator('#openPresensi').click();expect(page.locator('#presensiDialog')).to_be_visible();expect(page.locator('#presensiDialog .presensi-options > button')).to_have_count(3);page.locator('#presensiClose').click();expect(page.locator('#presensiDialog')).not_to_be_visible()
 page.locator('#openPresensi').click();page.locator('#openQR').click();expect(page.locator('#presensiDialog')).not_to_be_visible();expect(page.locator('#qrDialog')).to_be_visible();page.locator('#closeQR').click()
 page.locator('#openPresensi').click();page.locator('#quickLeave').click();expect(page.locator('#presensiDialog')).not_to_be_visible();expect(page.locator('#editDialog')).to_be_visible();page.locator('#cancelEdit').click()
 page.locator('#openPresensi').click();page.locator('#quickManual').click();expect(page.locator('#manualSearch')).to_have_value('');page.locator('#manualSearch').fill('Uji 31');page.locator('#manualResults button').first.click()
