 page.locator('#manualAbsent').check();assert page.locator('#manualStatus option').evaluate_all('els=>els.map(e=>e.value)')==['','sakit','izin','alpa'];expect(page.locator('#manualStatus')).to_have_value('');expect(page.locator('#manualStatus option').last).to_have_text('Tanpa Keterangan')
 for status in ['sakit','izin']:page.locator('#manualStatus').select_option(status);expect(page.locator('#manualEvidence')).to_be_visible()
 page.locator('#manualStatus').select_option('alpa');expect(page.locator('#manualEvidence')).not_to_be_visible();page.locator('#manualPresent').check();page.locator('#manualStatus').select_option('terlambat');page.locator('#manualReason').fill('Petugas mencatat keterlambatan')
 page.evaluate('window.hold=true;window.fail=true');page.locator('#manualSave').click();expect(page.locator('#manualSave')).to_be_disabled();expect(page.locator('#manualSearch')).to_be_disabled();expect(page.locator('#manualClose')).to_be_disabled();page.keyboard.press('Escape');expect(page.locator('#manualDialog')).to_be_visible();page.evaluate('window.hold=false;pending.splice(0).forEach(fn=>fn())');expect(page.locator('#manualMessage')).to_contain_text('Koneksi terputus');expect(page.locator('#manualStatus')).to_be_disabled();page.locator('#manualClose').click()
 page.locator('#openPresensi').click();page.locator('#quickManual').click();expect(page.locator('#manualSearch')).to_have_value('');page.locator('#manualSearch').fill('Uji 31');page.locator('#manualResults button').first.click();expect(page.locator('#manualReason')).to_have_value('Petugas mencatat keterlambatan');page.locator('#manualSave').click();expect(page.locator('#manualDialog')).not_to_be_visible();expect(page.locator('#total')).to_have_text('23');saved=page.evaluate("calls.filter(c=>c.arg?.nama==='simpanPresensiManualIndex').map(c=>c.arg.args[0])");assert len(saved)==2 and saved[0]==saved[1];page.locator('#search').fill('Uji 31');expect(page.locator('#tableBody')).to_contain_text('Terlambat · manual')
 # Optional evidence: invalid file sends no write; interrupted upload retains the upload ID;
