 page.locator('#search').fill('Uji 30');page.locator('#tableBody button[data-manual]').click();page.locator('#manualAbsent').check();page.locator('#manualStatus').select_option('sakit');page.locator('#manualEvidenceFile').set_input_files({'name':'bad.txt','mimeType':'text/plain','buffer':b'bad'});page.locator('#manualSave').click();expect(page.locator('#manualMessage')).to_contain_text('maksimal 5 MB');assert page.evaluate("calls.filter(c=>c.arg?.nama==='unggahBuktiIndex').length")==0
 page.locator('#manualEvidenceFile').set_input_files({'name':'surat.png','mimeType':'image/png','buffer':bytes([137,80,78,71,13,10,26,10,0])});page.evaluate('window.uploadFail=true');page.locator('#manualSave').click();expect(page.locator('#manualMessage')).to_contain_text('Unggah terputus');expect(page.locator('#manualEvidenceFile')).to_be_enabled();assert page.evaluate("calls.filter(c=>c.arg?.nama==='simpanPresensiManualIndex').length")==2
 page.evaluate('window.fail=true');page.locator('#manualSave').click();expect(page.locator('#manualMessage')).to_contain_text('Koneksi terputus');page.locator('#manualSave').click();expect(page.locator('#manualDialog')).not_to_be_visible();expect(page.locator('#total')).to_have_text('23');uploads=page.evaluate("calls.filter(c=>c.arg?.nama==='unggahBuktiIndex').map(c=>c.arg.args[0])");assert len(uploads)==2 and uploads[0]==uploads[1];payloads=page.evaluate("calls.filter(c=>c.arg?.nama==='simpanPresensiManualIndex').map(c=>c.arg.args[0])");assert payloads[-1]==payloads[-2] and payloads[-1]['id_bukti']=='PROOF-MANUAL-BROWSER'
 page.locator('#search').fill('Uji 30');page.locator('#tableBody button[data-manual]').click();expect(page.locator('#manualAbsent')).to_be_checked();expect(page.locator('#manualStatus')).to_have_value('sakit');expect(page.locator('#manualExistingEvidence')).to_contain_text('Bukti tersimpan');page.locator('#manualClose').click();page.locator('#tabIzin').click();sick=page.locator('#izinBody tr').filter(has_text='Peserta Uji 30');expect(sick).to_contain_text('Sakit');sick.get_by_role('button',name='Lihat bukti').click();expect(page.locator('#proofPreviewFrame')).to_have_attribute('src','https://drive.google.com/file/d/PROOF-MANUAL-BROWSER/preview');page.locator('#closeProofPreview').click();page.locator('#tabSesi').click();page.locator('#search').fill('');page.screenshot(path=str(out/'Monitoring-Presensi-Ringkas-Desktop.png'),full_page=True);assert not errors,errors;page.close()
